import 'package:flutter/material.dart';import '../core/utils/formatters.dart';import '../data/repositories/expense_repository.dart';
class DebtsScreen extends StatefulWidget{const DebtsScreen({super.key});@override State<DebtsScreen> createState()=>_DebtsScreenState();}
class _DebtsScreenState extends State<DebtsScreen>{final repo=ExpenseRepository();late Future<List<Map<String,Object?>>> future;@override void initState(){super.initState();future=repo.debts();}void reload()=>setState(()=>future=repo.debts());
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Debt tracker')),body:FutureBuilder<List<Map<String,Object?>>>(future:future,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.isEmpty)return const Center(child:Text('Track money you lend or borrow.'));return ListView(padding:const EdgeInsets.all(16),children:s.data!.map((e){final lend=e['direction']=='lent',remaining=e['remaining_minor'] as int;return Card(child:ListTile(title:Text(e['person'] as String,style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text((lend?'You lent':'You borrowed')+' • '+Fmt.money(remaining/100)+' remaining'),trailing:remaining==0?const Icon(Icons.check_circle,color:Colors.green):TextButton(onPressed:()=>settle(e['id'] as int,remaining),child:const Text('Settle'))));}).toList());}),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:const Text('Add debt')));
 Future<void> add()async{final person=TextEditingController(),amount=TextEditingController();String direction='lent';final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setD)=>AlertDialog(title:const Text('Add debt record'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:person,decoration:const InputDecoration(labelText:'Person or organisation')),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Amount',prefixText:'₹ ')),DropdownButtonFormField<String>(value:direction,items:const[DropdownMenuItem(value:'lent',child:Text('I lent money')),DropdownMenuItem(value:'borrowed',child:Text('I borrowed money'))],onChanged:(v)=>setD(()=>direction=v!))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),TextButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))])));final n=double.tryParse(amount.text);if(ok==true&&person.text.trim().isNotEmpty&&n!=null&&n>0){await repo.addDebt(person.text.trim(),direction,(n*100).round());reload();}person.dispose();amount.dispose();}
 Future<void> settle(int id,int remaining)async{final amount=TextEditingController(text:(remaining/100).toStringAsFixed(2));final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Record repayment'),content:TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Amount',prefixText:'₹ ')),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),TextButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))]));final n=double.tryParse(amount.text);if(ok==true&&n!=null&&n>0){await repo.settleDebt(id,(n*100).round());reload();}amount.dispose();}
}
